def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    strong_prev = 0.0
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                b = float(bid)
                prev_bids.append(b)
                if b > strong_prev:
                    strong_prev = b

    if not alive:
        safe = DAILY_SALARY * 0.35
        if hp <= 3 or no_water_days >= 1:
            safe = DAILY_SALARY * 0.6
        return float(max(0.0, min(budget, safe)))

    supply_pressure = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_pressure < 0:
        supply_pressure = 0.0
    if supply_pressure > 1:
        supply_pressure = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 0.75
    elif hp <= 4:
        urgency += 0.45
    elif hp <= 6:
        urgency += 0.2

    if no_water_days >= 2:
        urgency += 0.8
    elif no_water_days >= 1:
        urgency += 0.35

    urgency += 0.35 * supply_pressure
    if day >= 8:
        urgency += 0.1

    cindy_alive = False
    cindy_prev = None
    bob_prev = None
    for oid, opp in opponents_status.items():
        if not opp.get('alive'):
            continue
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if oid == 'Cindy':
            cindy_alive = True
            if bid is not None:
                cindy_prev = float(bid)
        if oid == 'Bob' and bid is not None:
            bob_prev = float(bid)

    if urgency < 0.35 and cindy_alive and cindy_prev is not None and cindy_prev >= 85:
        bid = DAILY_SALARY * (0.22 + 0.18 * (1.0 - supply_pressure))
        return float(max(0.0, min(budget, bid)))

    target = 0.0
    if bob_prev is not None:
        target = max(target, bob_prev + 2.0)
    if cindy_prev is not None:
        if urgency >= 0.7:
            target = max(target, cindy_prev + 1.5)
        else:
            target = max(target, min(cindy_prev - 10.0, DAILY_SALARY * 0.95))
    if strong_prev > 0:
        target = max(target, strong_prev * 0.92)

    base = DAILY_SALARY * (0.38 + 0.42 * urgency + 0.12 * supply_pressure)
    bid = max(base, target)

    if urgency >= 1.0:
        bid = max(bid, DAILY_SALARY * 0.96)
    elif urgency >= 0.7:
        bid = max(bid, DAILY_SALARY * 0.82)
    elif urgency < 0.25:
        bid = min(bid, DAILY_SALARY * 0.58)

    if budget < DAILY_SALARY * 0.8:
        bid = min(bid, budget * 0.92)

    if hp <= 1 or no_water_days >= 2:
        bid = max(bid, min(budget, DAILY_SALARY * 0.98))

    bid = max(0.0, min(budget, bid))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append(o)

    # If nobody alive, conserve.
    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from each opponent's previous_trace (immediate reaction only).
    yesterday_bids = []
    for o in alive:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Estimate opponent pressure: focus on high bidder (likely Cindy-like behavior).
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Supply-based aggressiveness: with higher supply, competition matters more.
    # Map supply in [15,25] to a multiplier in [0.9,1.2].
    if MAX_SUPPLY - MIN_SUPPLY > 0:
        t = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        t = 0.5
    t = max(0.0, min(1.0, float(t)))
    supply_mult = 0.9 + 0.3 * t

    # If I'm in danger, bid much closer to the pressure level.
    danger = 0
    if hp <= 2.0:
        danger += 2
    if no_water_days >= 2:
        danger += 1

    # Base target: undercut the highest previous bidder unless in danger.
    # Typical strategy: bid slightly below their max/pressure to win at lower cost.
    if highest_prev_bid > 0:
        if danger >= 2:
            target = highest_prev_bid * 0.98
        elif danger == 1:
            target = highest_prev_bid * 0.9
        else:
            target = highest_prev_bid * 0.78
    else:
        target = DAILY_SALARY * 0.55

    # Apply supply multiplier and keep within reasonable bounds.
    target *= supply_mult

    # Also cap by a fraction of daily salary to avoid over-spending.
    # When hp is safe, be conservative.
    if danger == 0:
        cap = DAILY_SALARY * 0.62
    elif danger == 1:
        cap = DAILY_SALARY * 0.85
    else:
        cap = DAILY_SALARY * 0.95

    bid = min(target, cap, budget)

    # Ensure non-negative and at least a small meaningful bid if budget allows.
    if bid < 0.0:
        bid = 0.0
    min_bid = 1.0
    if budget >= min_bid and bid < min_bid:
        bid = min_bid

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_survivors = len(alive_opponents) + 1

    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace')]

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    if not yesterday_bids:
        return min(my_status['budget'], DAILY_SALARY * 0.6)

    max_prev = max(yesterday_bids)
    avg_prev = sum(yesterday_bids) / len(yesterday_bids)

    if supply / num_survivors >= WATER_REQ:
        return min(my_status['budget'], max(DAILY_SALARY * 0.4, avg_prev * 0.9))
    else:
        return min(my_status['budget'], max(DAILY_SALARY * 0.6, max_prev + 2.0))
